    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum UserStatus {\n  PENDING // user signed up but an email is not verified yet\n  ACTIVE // active account\n  SUSPENDED // temporarily disabled by an administrator\n  LOCKED // automatically locked after too many failed login\n  DEACTIVATED // user voluntarily deactivated his account. can be reactivated\n  DELETED // ineccessible, retained for audit purposes\n}\n\nmodel User {\n  id                  String               @id @default(ulid())\n  email               String               @unique\n  passwordHash        String               @map(\"password_hash\")\n  firstName           String               @map(\"first_name\")\n  lastName            String               @map(\"last_name\")\n  status              UserStatus           @default(PENDING)\n  emailVerified       Boolean              @default(false) @map(\"email_verified\")\n  createdAt           DateTime             @default(now()) @map(\"created_at\")\n  updatedAt           DateTime             @updatedAt @map(\"updated_at\")\n  lastSeenAt          DateTime?            @map(\"last_seen\")\n  organizationMembers OrganizationMember[]\n  sessions            Session[]\n  auditLogs           AuditLog[]\n  createdInvitations  Invitation[]         @relation(\"InvitationCreatedBy\")\n\n  @@map(\"user\")\n}\n\nmodel Organization {\n  id                  String               @id @default(ulid())\n  name                String               @unique\n  slug                String               @unique // slug name of the company\n  taxNo               String?              @unique @map(\"tax_number\")\n  address             String?\n  createdAt           DateTime             @default(now()) @map(\"created_at\")\n  roles               Role[]\n  organizationMembers OrganizationMember[]\n  invitations         Invitation[]\n  auditLogs           AuditLog[]\n\n  @@map(\"organization\")\n}\n\nenum MemberStatus {\n  INVITED\n  ACTIVE\n  SUSPENDED\n  REMOVED\n}\n\nmodel OrganizationMember {\n  id             String       @id @default(uuid())\n  organizationId String       @map(\"organization_id\")\n  organization   Organization @relation(fields: [organizationId], references: [id])\n  userId         String       @map(\"user_id\")\n  user           User         @relation(fields: [userId], references: [id])\n  roleId         String       @map(\"role_id\")\n  role           Role         @relation(fields: [roleId], references: [id])\n  status         MemberStatus // user can belong to multiple organizations, and their status can differ in each other\n  joinedAt       DateTime     @default(now()) @map(\"joined_at\")\n\n  @@unique([organizationId, userId])\n  @@map(\"organization_member\")\n}\n\nenum RoleNames {\n  SUPERADMIN\n  ADMIN\n  MANAGER\n  DIRECTOR\n  EMPLOYEE\n  VIEWER\n}\n\nmodel Role {\n  id                  String               @id @default(ulid())\n  organizationId      String               @map(\"organization_id\")\n  organization        Organization         @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  name                RoleNames            @default(VIEWER)\n  description         String\n  isSystem            Boolean              @default(false) @map(\"is_system\") // if true the deletion of this record must be impossible, for security reasons\n  organizationMembers OrganizationMember[]\n  rolePermissions     RolePermission[]\n  invitations         Invitation[]\n\n  @@map(\"role\")\n}\n\nmodel Permission {\n  id              String           @id @default(ulid())\n  resource        String // authorization subject like users, invoices, business subjects like resource/svyion -> purchase:po(purchase order) + create, approve or cancel\n  action          String // create, view, delete, update, approve, cancel etc\n  rolePermissions RolePermission[]\n\n  @@map(\"permission\")\n}\n\nmodel RolePermission {\n  roleId       String     @map(\"role_id\")\n  role         Role       @relation(fields: [roleId], references: [id])\n  permissionId String     @map(\"permission_id\")\n  permission   Permission @relation(fields: [permissionId], references: [id])\n\n  @@unique([roleId, permissionId])\n  @@map(\"role_permission\")\n}\n\nmodel Invitation {\n  id              String       @id @default(uuid())\n  organizationId  String       @map(\"organization_id\")\n  organization    Organization @relation(fields: [organizationId], references: [id])\n  email           String\n  roleId          String       @map(\"role_id\")\n  role            Role         @relation(fields: [roleId], references: [id])\n  token           String       @unique\n  expiresAt       DateTime     @map(\"expires_at\")\n  acceptedAt      DateTime?    @map(\"accepted_at\")\n  createdByUserId String?      @map(\"created_by\")\n  createdByUser   User?        @relation(\"InvitationCreatedBy\", fields: [createdByUserId], references: [id], onDelete: SetNull)\n\n  @@map(\"invitation\")\n}\n\nmodel Session {\n  id             String    @id @default(uuid())\n  userId         String    @map(\"user_id\")\n  user           User      @relation(fields: [userId], references: [id])\n  ip             String? // ip from where the session opened\n  userAgent      String?   @map(\"user_agent\") // browser/mobile/\n  lastActivity   DateTime  @map(\"last_activity\")\n  expiresAt      DateTime  @map(\"expires_at\")\n  revokedAt      DateTime? @map(\"revoked_at\")\n  revokedReason  String?   @map(\"revoked_reason\")\n  refreshVersion Int       @default(0) @map(\"refresh_version\")\n  createdAt      DateTime  @default(now()) @map(\"created_at\")\n\n  @@map(\"session\")\n}\n\nenum ResourceType {\n  USER\n  ORGANIZATION\n  ROLE\n  PERMISSION\n  INVITATION\n  SESSION\n  API_KEY\n}\n\nenum AuditAction {\n  // Authentication\n  LOGIN\n  LOGIN_FAILED\n  LOGOUT\n  REFRESH_TOKEN\n  SESSION_REVOKED\n  PASSWORD_CHANGED\n  PASSWORD_RESET_REQUESTED\n  PASSWORD_RESET_COMPLETED\n  EMAIL_VERIFIED\n\n  // User\n  USER_CREATED\n  USER_UPDATED\n  USER_DEACTIVATED\n  USER_REACTIVATED\n  USER_DELETED\n\n  // Organization\n  ORGANIZATION_CREATED\n  ORGANIZATION_UPDATED\n  ORGANIZATION_DELETED\n  ORGANIZATION_TRANSFERRED\n\n  // Membership\n  MEMBER_INVITED\n  MEMBER_JOINED\n  MEMBER_REMOVED\n\n  // Roles\n  ROLE_CREATED\n  ROLE_UPDATED\n  ROLE_DELETED\n  ROLE_ASSIGNED\n  ROLE_REMOVED\n\n  // Permissions\n  PERMISSION_GRANTED\n  PERMISSION_REVOKED\n\n  // Security\n  MFA_ENABLED\n  MFA_DISABLED\n  ACCOUNT_LOCKED\n  ACCOUNT_UNLOCKED\n}\n\nmodel AuditLog {\n  id             String        @id @default(cuid())\n  organizationId String?       @map(\"organization_id\")\n  organization   Organization? @relation(fields: [organizationId], references: [id], onDelete: SetNull)\n  userId         String?       @map(\"user_id\")\n  user           User?         @relation(fields: [userId], references: [id], onDelete: SetNull)\n  action         AuditAction\n  resource       ResourceType\n  resourceId     String?       @map(\"resource_id\")\n  metadata       Json?\n  ip             String?\n  userAgent      String?       @map(\"user_agent\")\n  createdAt      DateTime      @default(now()) @map(\"created_at\")\n\n  @@index([organizationId, createdAt])\n  @@index([userId, createdAt])\n  @@index([resource, resourceId, createdAt])\n  @@index([action, createdAt])\n  @@map(\"audit_log\")\n}\n",
